import{_ as t,o as a,c as o,a3 as n}from"./chunks/framework.DNWyyI0w.js";const p=JSON.parse('{"title":"Why Saidi","description":"","frontmatter":{},"headers":[],"relativePath":"introduction/why-saidi.md","filePath":"introduction/why-saidi.md"}'),r={name:"introduction/why-saidi.md"};function i(s,e,d,c,h,l){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="why-saidi" tabindex="-1">Why Saidi <a class="header-anchor" href="#why-saidi" aria-label="Permalink to &quot;Why Saidi&quot;">​</a></h1><h2 id="the-problem-with-a-chat-window" tabindex="-1">The problem with a chat window <a class="header-anchor" href="#the-problem-with-a-chat-window" aria-label="Permalink to &quot;The problem with a chat window&quot;">​</a></h2><p>A single long chat session has three failure modes that get worse the more real the work gets:</p><ol><li><strong>Context dies.</strong> The session compacts, the details go, and the model quietly starts working from a summary of a summary.</li><li><strong>The goalposts move.</strong> An agent that decides what happens next on every step can re-scope the objective mid-flight and then report success against the new scope.</li><li><strong>&quot;Done&quot; is self-reported.</strong> The same model that wrote the code writes the claim that the code works.</li></ol><p>Saidi is built around removing those three, one mechanism at a time.</p><h2 id="one-shared-context-on-one-branch" tabindex="-1">One shared context, on one branch <a class="header-anchor" href="#one-shared-context-on-one-branch" aria-label="Permalink to &quot;One shared context, on one branch&quot;">​</a></h2><p>A Run keeps a participant record per agent, each with its own resumable provider session and — for coding work — <strong>one</strong> branch it accumulates commits on. A second delegation to the same project resumes the same thread instead of starting cold on a fresh branch. When a session <em>is</em> compacted, the participant is flagged <code>memoryStale</code> and the next delegation re-sends the memory block, because a compact summary is exactly where durable facts go to die.</p><h2 id="a-frozen-plan-and-drift-you-can-see" tabindex="-1">A frozen plan, and drift you can see <a class="header-anchor" href="#a-frozen-plan-and-drift-you-can-see" aria-label="Permalink to &quot;A frozen plan, and drift you can see&quot;">​</a></h2><p><code>Run.originalChecklist</code> holds the plan exactly as first frozen, alongside the live checklist. <code>planVersion</code> is bumped by every accepted amendment — <code>1</code> means the plan was right the first time. Without that pair, an amended plan is indistinguishable from a plan that never needed amending.</p><p>In <strong>guided</strong> execution mode the <em>engine</em> owns the dispatch loop: it selects ready tasks from the frozen plan, batches independent ones, verifies each result, and advances. PRIME plans once, answers escalations, and summarises. <strong>Autonomous</strong> mode is still there for genuinely exploratory work, where re-planning mid-flight is the point.</p><h2 id="verdicts-from-somewhere-else" tabindex="-1">Verdicts from somewhere else <a class="header-anchor" href="#verdicts-from-somewhere-else" aria-label="Permalink to &quot;Verdicts from somewhere else&quot;">​</a></h2><p>Every completed task gets a <code>TaskVerification</code> with a <code>by</code> field: <code>command</code> (a real shell command judged by exit code), <code>model</code> (an independent verifier pass), <code>evidence</code>, or <code>none</code>. Verdicts append to a run-level <code>verificationLog</code> that survives plan amendments — because the task an orchestrator drops is usually the one that kept failing, and dropping it used to take its whole failure history with it.</p><p>The trust asymmetry is deliberate: <strong>any</strong> check can fail a task, but only a <em>trusted</em> check — one from project config or an operator, never one the plan author wrote — can mark a criterion proven.</p><h2 id="bounded-by-construction" tabindex="-1">Bounded by construction <a class="header-anchor" href="#bounded-by-construction" aria-label="Permalink to &quot;Bounded by construction&quot;">​</a></h2><ul><li>Your workspace is the boundary. Agents, runs, memory, connections and the credit ledger belong to one workspace and never cross into another.</li><li>Runs and chats belong to whoever created them. No role — owner included — reads another member&#39;s work unless it was explicitly shared.</li><li>Memory is plain markdown you can read, scoped per member, per project and per agent. It lives in Saidi and is never committed into a client repo.</li><li>Nothing about your repo reaches an outside service unless you wire that connection yourself, and every outbound call is a tool call in the run thread.</li></ul><p>The positioning, stated plainly: <strong>you manage; they run.</strong></p><p>Next: <a href="/docs/quickstart/getting-started">Getting Started</a>.</p>',17)])])}const u=t(r,[["render",i]]);export{p as __pageData,u as default};
